def infer(
    self,
    text,
    stream=False,
    lang=None,
    skip_refine_text=False,
    refine_text_only=False,
    use_decoder=True,
    do_text_normalization=True,
    do_homophone_replacement=True,
    split_text=True,
    max_split_batch=4,
    params_refine_text=RefineTextParams(),
    params_infer_code=InferCodeParams(),
):
    self.context.set(False)

    if split_text and isinstance(text, str):
        if "\n" in text:
            text = text.split("\n")
        else:
            text = re.split(r"(?<=。)|(?<=\.\s)", text)
            nt = []
            if isinstance(text, list):
                for t in text:
                    if t:
                        nt.append(t)
                text = nt
            else:
                text = [text]
        self.logger.info("split text into %d parts", len(text))
        self.logger.debug("%s", str(text))

    if len(text) == 0:
        return []

    res_gen = self._infer(
        text,
        stream,
        lang,
        skip_refine_text,
        refine_text_only,
        use_decoder,
        do_text_normalization,
        do_homophone_replacement,
        split_text,
        max_split_batch,
        params_refine_text,
        params_infer_code,
    )
    if stream:
        return res_gen
    elif not refine_text_only:
        stripped_wavs = []
        thr = np.float32(1e-5)
        for wavs in res_gen:
            for wav in wavs:
                stripped_wavs.append(wav[np.abs(wav) > thr])
        if split_text:
            return [np.concatenate(stripped_wavs)]
        return stripped_wavs
    else:
        return next(res_gen)

def _get_contributors_from_commits(api: Github, commits: list[Commit]) -> set[str]:
    """Get a set of contributors from a set of commits."""
    # Get authors and co-authors from the commits
    contributors: set[str] = set()
    coauthor_names_emails: set[tuple[str, str]] = set()
    coauthor_pattern = r"Co-authored-by:\s*(.+?)\s*<(.+?)>"

    for commit in commits:
        if commit.author.name is None:
            continue
        if "[bot]" in commit.author.name:
            continue
        # Find co-authors in the commit message
        matches: list[str] = re.findall(coauthor_pattern, commit.message)

        contributors.add(commit.author.name)
        if matches:
            coauthor_names_emails.update(matches)

    # Get full names of the GitHub usernames
    def _get_user(username: str, email: str) -> Optional[str]:
        try:
            user = api.get_user(username)
            if user.email == email:
                return user.name
            print(f"Email mismatch for user {username}: {email} != {user.email}")
        except Exception:  # pylint: disable=broad-exception-caught
            print(
                f"Failed to retrieve GitHub profile for user '{username}' <{email}>. "
                f"Using '{username}' directly in the changelog."
            )
            return username
        return None

    with ThreadPoolExecutor(max_workers=MAX_WORKERS) as executor:
        for name in executor.map(lambda x: _get_user(*x), coauthor_names_emails):
            if name:
                contributors.add(name)
    return contributors

def count_bytes(self) -> int:
    """Return number of Bytes stored in this object.

    This function counts booleans as occupying 1 Byte.
    """

    def get_var_bytes(value: ConfigScalar) -> int:
        """Return Bytes of value passed."""
        var_bytes = 0
        if isinstance(value, bool):
            var_bytes = 1
        elif isinstance(value, (int, float)):
            var_bytes = (
                8  # the profobufing represents int/floats in ConfigRecords as 64bit
            )
        if isinstance(value, (str, bytes)):
            var_bytes = len(value)
        if var_bytes == 0:
            raise ValueError(
                "Config values must be either `bool`, `int`, `float`, "
                "`str`, or `bytes`"
            )
        return var_bytes

    num_bytes = 0

    for k, v in self.items():
        if isinstance(v, list):
            if isinstance(v[0], (bytes, str)):
                # not all str are of equal length necessarily
                # for both the footprint of each element is 1 Byte
                num_bytes += int(sum(len(s) for s in v))  # type: ignore
            else:
                num_bytes += get_var_bytes(v[0]) * len(v)
        else:
            num_bytes += get_var_bytes(v)

        # We also count the bytes footprint of the keys
        num_bytes += len(k)

    return num_bytes

