from functools import wraps
from unittest.mock import MagicMock, patch

from taipy.rest.api.middlewares._middleware import _middleware


def mock_enterprise_middleware(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        return f(*args, **kwargs)

    return wrapper


@patch("taipy.common._modules.EnterpriseEdition._is_installed")
@patch("taipy.rest.api.middlewares._middleware._enterprise_middleware")
def test_enterprise_middleware_applied_when_enterprise_is_installed(
    enterprise_middleware: MagicMock, is_enterprise_installed: MagicMock
):
    enterprise_middleware.return_value = mock_enterprise_middleware
    is_enterprise_installed.return_value = True

    @_middleware
    def f():
        return "f"

    rv = f()
    assert rv == "f"
    is_enterprise_installed.assert_called_once()
    enterprise_middleware.assert_called_once()


@patch("taipy.common._modules.EnterpriseEdition._is_installed")
@patch("taipy.rest.api.middlewares._middleware._enterprise_middleware")
def test_enterprise_middleware_not_applied_when_enterprise_is_not_installed(
    enterprise_middleware: MagicMock, is_enterprise_installed: MagicMock
):
    enterprise_middleware.return_value = mock_enterprise_middleware
    is_enterprise_installed.return_value = False

    @_middleware
    def f():
        return "f"

    rv = f()
    assert rv == "f"
    is_enterprise_installed.assert_called_once()
    enterprise_middleware.assert_not_called()

def __request_data_update(self, var_name: str, payload: t.Any) -> None:
    # Use custom attrgetter function to allow value binding for _MapDict
    newvalue = _getscopeattr_drill(self, var_name)  # type: ignore[arg-type]
    custom_page_filtered_types = _Hooks()._get_resource_handler_data_layer_supported_types()
    if not isinstance(newvalue, _TaipyData) and isinstance(newvalue, custom_page_filtered_types):  # type: ignore
        newvalue = _TaipyData(newvalue, "")
    if isinstance(newvalue, _TaipyData):
        ret_payload = None
        if isinstance(payload, dict):
            self.__update_state_context(payload)
            lib_name = payload.get("library")
            if isinstance(lib_name, str):
                libs = self.__extensions.get(lib_name, [])
                for lib in libs:
                    user_var_name = var_name
                    try:
                        with contextlib.suppress(NameError):
                            # ignore name error and keep var_name
                            user_var_name = self._get_real_var_name(var_name)[0]
                        ret_payload = lib.get_data(lib_name, payload, user_var_name, newvalue)
                        if ret_payload:
                            break
                    except Exception as e:  # pragma: no cover
                        _warn(
                            f"Exception raised in '{lib_name}.get_data({lib_name}, payload, {user_var_name}, value)'",  # noqa: E501
                            e,
                        )
        if not isinstance(ret_payload, dict):
            ret_payload = self._get_accessor().get_data(var_name, newvalue, payload)
        self.__send_ws_update_with_dict({var_name: ret_payload})

def __send_ws(self, payload: dict, allow_grouping=True, send_back_only=False) -> None:
    grouping_message = self.__get_message_grouping() if allow_grouping else None
    if grouping_message is None:
        try:
            self._server._ws.emit(
                "message",
                payload,
                to=t.cast(str, self.__get_ws_receiver(send_back_only)),
            )
            time.sleep(0.001)
        except Exception as e:  # pragma: no cover
            _warn(f"Exception raised in WebSocket communication in '{self.__frame.f_code.co_name}'", e)
    else:
        grouping_message.append(payload)

def __send_ack(self, ack_id: t.Optional[str]) -> None:
    if ack_id:
        try:
            self._server._ws.emit(
                "message",
                {"type": _WsType.ACKNOWLEDGEMENT.value, "id": ack_id},
                to=t.cast(str, self.__get_ws_receiver(True)),
            )
            time.sleep(0.001)
        except Exception as e:  # pragma: no cover
            _warn(f"Exception raised in WebSocket communication (send ack) in '{self.__frame.f_code.co_name}'", e)

def __get_ws_receiver(self, send_back_only=False) -> t.Union[t.List[str], t.Any, None]:
    if self._bindings()._is_single_client():
        return None
    sid = getattr(request, "sid", None) if request else None
    sids = self.__get_sids(self._get_client_id())
    if sid:
        sids.add(sid)
        if send_back_only:
            return sid
    return list(sids)

def __call_function_with_args(self, **kwargs):
    action_function = kwargs.get("action_function")
    id = t.cast(str, kwargs.get("id"))
    payload = kwargs.get("payload")

    if _is_function(action_function):
        try:
            try:
                args = [self._get_real_var_name(id)[0], payload]
            except Exception:
                args = [id, payload]
            self._call_function_with_state(t.cast(t.Callable, action_function), args)
        except Exception as e:  # pragma: no cover
            if not self._call_on_exception(action_function, e):
                _warn(f"on_action(): Exception raised in '{_function_name(action_function)}()'", e)
        return True
    return False

def __delete_csv(self, state: State, var_name: str, payload: dict):
    try:
        (Path(tempfile.gettempdir()) / t.cast(str, payload.get("args", [])[-1]).split("/")[-1]).unlink(True)
    except Exception:
        pass

def _set_css_file(self, css_file: t.Optional[str] = None):
    script_file = Path(self.__frame.f_code.co_filename or ".").resolve()
    if css_file is None:
        if script_file.with_suffix(".css").exists():
            css_file = f"{script_file.stem}.css"
        elif script_file.is_dir() and (script_file / "taipy.css").exists():
            css_file = "taipy.css"
    if css_file is None:
        script_file = script_file.with_name("taipy").with_suffix(".css")
        if script_file.exists():
            css_file = f"{script_file.stem}.css"
    self.__css_file = css_file

class Element:
    """
    The definition of a custom visual element.

    An element is defined by its properties (name, type and default value) and
    what the default property name is.
    """

    __RE_PROP_VAR = re.compile(r"<tp:prop:(\w+)>")
    __RE_UNIQUE_VAR = re.compile(r"<tp:uniq:(\w+)>")

    def __init__(
        self,
        default_property: str,
        properties: t.Dict[str, ElementProperty],
        react_component: t.Optional[str] = None,
        render_xhtml: t.Optional[t.Callable[[t.Dict[str, t.Any]], str]] = None,
        inner_properties: t.Optional[t.Dict[str, ElementProperty]] = None,
    ) -> None:
        """Initializes a new custom element declaration.

        If *render_xhtml* is specified, then this is a static element, and
        *react_component* is ignored.

        Arguments:
            default_property (str): The name of the default property for this element.
            properties (Dict[str, ElementProperty]): The dictionary containing the properties of this element, where the keys are the property names and the values are instances of ElementProperty.
            inner_properties (Optional[List[ElementProperty]]): The optional list of inner properties for this element.<br/>
                Default values are set/binded automatically.
            react_component (Optional[str]): The name of the component to be created on the front-end.<br/>
                If not specified, it is set to a camel case version of the element's name
                ("one_name" is transformed to "OneName").
            render_xhtml (Optional[callable[[dict[str, Any]], str]]): A function that receives a
                dictionary containing the element's properties and their values
                and that must return a valid XHTML string.
        """  # noqa: E501
        self.default_attribute = default_property
        self.attributes = properties
        self.inner_properties = inner_properties
        self.js_name = react_component
        if callable(render_xhtml):
            self._render_xhtml = render_xhtml
        super().__init__()

    def _get_js_name(self, name: str) -> str:
        return self.js_name or _to_camel_case(name, True)

    def check(self, name: str):
        if not isinstance(name, str) or not name or not name.isidentifier():
            _warn(f"Invalid element name: '{name}'.")
        default_found = False
        if self.attributes:
            for prop_name, property in self.attributes.items():
                if isinstance(property, ElementProperty):
                    property.check(name, prop_name)
                    if not default_found:
                        default_found = self.default_attribute == prop_name
                else:
                    _warn(f"Property must inherit from 'ElementProperty' '{name}.{prop_name}'.")
        if not default_found:
            _warn(f"Element {name} has no default property.")

    def _is_server_only(self):
        return hasattr(self, "_render_xhtml") and callable(self._render_xhtml)

    def _call_builder(
        self,
        name,
        gui: "Gui",
        properties: t.Optional[t.Dict[str, t.Any]],
        lib: "ElementLibrary",
        is_html: t.Optional[bool] = False,
        counter: int = 0,
    ) -> t.Union[t.Any, t.Tuple[str, str]]:
        attributes = properties if isinstance(properties, dict) else {}
        if self.inner_properties:
            uniques: t.Dict[str, int] = {}
            self.attributes.update(
                {
                    prop: ElementProperty(attr.property_type, None, attr._js_name, attr.with_update)
                    for prop, attr in self.inner_properties.items()
                }
            )
            for prop, attr in self.inner_properties.items():
                val = attr.default_value
                if val:
                    # handling property replacement in inner properties <tp:prop:...>
                    while m := Element.__RE_PROP_VAR.search(val):
                        var = attributes.get(m.group(1))
                        hash_value = None if var is None else gui._evaluate_expr(var)
                        if hash_value:
                            names = gui._get_real_var_name(hash_value)
                            hash_value = names[0] if isinstance(names, tuple) else names
                        else:
                            hash_value = "None"
                        val = val[: m.start()] + hash_value + val[m.end() :]
                    # handling unique id replacement in inner properties <tp:uniq:...>
                    has_uniq = False
                    while m := Element.__RE_UNIQUE_VAR.search(val):
                        has_uniq = True
                        id = uniques.get(m.group(1))
                        if id is None:
                            id = len(uniques) + 1
                            uniques[m.group(1)] = id
                        val = f"{val[: m.start()]}{counter}{id}{val[m.end() :]}"
                    if has_uniq and gui._is_expression(val):
                        gui._evaluate_expr(val, True)

                attributes[prop] = val
        # this modifies attributes
        hash_names = _Builder._get_variable_hash_names(gui, attributes)  # variable replacement
        # call user render if any
        if self._is_server_only():
            xhtml = self._render_xhtml(attributes)
            try:
                xml_root = etree.fromstring(xhtml)
                return (xhtml, name) if is_html else xml_root

            except Exception as e:
                _warn(f"{name}.render_xhtml() did not return a valid XHTML string", e)
                return f"{name}.render_xhtml() did not return a valid XHTML string. {e}"
        else:
            default_attr: t.Optional[ElementProperty] = None
            default_value = None
            default_name = None
            attrs = []
            if self.attributes:
                for prop_name, property in self.attributes.items():
                    if isinstance(property, ElementProperty):
                        if self.default_attribute == prop_name:
                            default_name = prop_name
                            default_attr = property
                            default_value = property.default_value
                        else:
                            attrs.append(property._get_tuple(prop_name))
            elt_built = _Builder(
                gui=gui,
                control_type=name,
                element_name=f"{lib.get_js_module_name()}_{self._get_js_name(name)}",
                attributes=properties,
                hash_names=hash_names,
                lib_name=lib.get_name(),
                default_value=default_value,
            )
            if default_attr is not None:
                elt_built.set_value_and_default(
                    var_name=default_name,
                    var_type=t.cast(PropertyType, default_attr.property_type),
                    default_val=default_attr.default_value,
                    with_default=default_attr.property_type != PropertyType.data,
                )
            elt_built.set_attributes(attrs)
            return elt_built._build_to_string() if is_html else elt_built.el

def __format_configs_parameter(clazz, parameter) -> List[str]:
    if isinstance(parameter, str):
        parameter = [parameter]
    if isinstance(parameter, clazz):
        parameter = [parameter.id]  # type: ignore[attr-defined]
    if isinstance(parameter, list):
        parameter = [cfg.id if isinstance(cfg, clazz) else cfg for cfg in parameter]  # type: ignore[attr-defined]
    return parameter

