async def apipeline_enqueue_documents(
    self,
    input: str | list[str],
    ids: list[str] | None = None,
    file_paths: str | list[str] | None = None,
    track_id: str | None = None,
) -> str:
    """
    Pipeline for Processing Documents

    1. Validate ids if provided or generate MD5 hash IDs and remove duplicate contents
    2. Generate document initial status
    3. Filter out already processed documents
    4. Enqueue document in status

    Args:
        input: Single document string or list of document strings
        ids: list of unique document IDs, if not provided, MD5 hash IDs will be generated
        file_paths: list of file paths corresponding to each document, used for citation
        track_id: tracking ID for monitoring processing status, if not provided, will be generated with "enqueue" prefix

    Returns:
        str: tracking ID for monitoring processing status
    """
    # Generate track_id if not provided
    if track_id is None or track_id.strip() == "":
        track_id = generate_track_id("enqueue")
    if isinstance(input, str):
        input = [input]
    if isinstance(ids, str):
        ids = [ids]
    if isinstance(file_paths, str):
        file_paths = [file_paths]

    # If file_paths is provided, ensure it matches the number of documents
    if file_paths is not None:
        if isinstance(file_paths, str):
            file_paths = [file_paths]
        if len(file_paths) != len(input):
            raise ValueError(
                "Number of file paths must match the number of documents"
            )
    else:
        # If no file paths provided, use placeholder
        file_paths = ["unknown_source"] * len(input)

    # 1. Validate ids if provided or generate MD5 hash IDs and remove duplicate contents
    if ids is not None:
        # Check if the number of IDs matches the number of documents
        if len(ids) != len(input):
            raise ValueError("Number of IDs must match the number of documents")

        # Check if IDs are unique
        if len(ids) != len(set(ids)):
            raise ValueError("IDs must be unique")

        # Generate contents dict and remove duplicates in one pass
        unique_contents = {}
        for id_, doc, path in zip(ids, input, file_paths):
            cleaned_content = sanitize_text_for_encoding(doc)
            if cleaned_content not in unique_contents:
                unique_contents[cleaned_content] = (id_, path)

        # Reconstruct contents with unique content
        contents = {
            id_: {"content": content, "file_path": file_path}
            for content, (id_, file_path) in unique_contents.items()
        }
    else:
        # Clean input text and remove duplicates in one pass
        unique_content_with_paths = {}
        for doc, path in zip(input, file_paths):
            cleaned_content = sanitize_text_for_encoding(doc)
            if cleaned_content not in unique_content_with_paths:
                unique_content_with_paths[cleaned_content] = path

        # Generate contents dict of MD5 hash IDs and documents with paths
        contents = {
            compute_mdhash_id(content, prefix="doc-"): {
                "content": content,
                "file_path": path,
            }
            for content, path in unique_content_with_paths.items()
        }

    # 2. Generate document initial status (without content)
    new_docs: dict[str, Any] = {
        id_: {
            "status": DocStatus.PENDING,
            "content_summary": get_content_summary(content_data["content"]),
            "content_length": len(content_data["content"]),
            "created_at": datetime.now(timezone.utc).isoformat(),
            "updated_at": datetime.now(timezone.utc).isoformat(),
            "file_path": content_data[
                "file_path"
            ],  # Store file path in document status
            "track_id": track_id,  # Store track_id in document status
        }
        for id_, content_data in contents.items()
    }

    # 3. Filter out already processed documents
    # Get docs ids
    all_new_doc_ids = set(new_docs.keys())
    # Exclude IDs of documents that are already enqueued
    unique_new_doc_ids = await self.doc_status.filter_keys(all_new_doc_ids)

    # Log ignored document IDs (documents that were filtered out because they already exist)
    ignored_ids = list(all_new_doc_ids - unique_new_doc_ids)
    if ignored_ids:
        for doc_id in ignored_ids:
            file_path = new_docs.get(doc_id, {}).get("file_path", "unknown_source")
            logger.warning(
                f"Ignoring document ID (already exists): {doc_id} ({file_path})"
            )
        if len(ignored_ids) > 3:
            logger.warning(
                f"Total Ignoring {len(ignored_ids)} document IDs that already exist in storage"
            )

    # Filter new_docs to only include documents with unique IDs
    new_docs = {
        doc_id: new_docs[doc_id]
        for doc_id in unique_new_doc_ids
        if doc_id in new_docs
    }

    if not new_docs:
        logger.warning("No new unique documents were found.")
        return

    # 4. Store document content in full_docs and status in doc_status
    #    Store full document content separately
    full_docs_data = {
        doc_id: {"content": contents[doc_id]["content"]}
        for doc_id in new_docs.keys()
    }
    await self.full_docs.upsert(full_docs_data)
    # Persist data to disk immediately
    await self.full_docs.index_done_callback()

    # Store document status (without content)
    await self.doc_status.upsert(new_docs)
    logger.debug(f"Stored {len(new_docs)} new unique documents")

    return track_id

def merge_entities(
    self,
    source_entities: list[str],
    target_entity: str,
    merge_strategy: dict[str, str] = None,
    target_entity_data: dict[str, Any] = None,
) -> dict[str, Any]:
    loop = always_get_an_event_loop()
    return loop.run_until_complete(
        self.amerge_entities(
            source_entities, target_entity, merge_strategy, target_entity_data
        )
    )

async def upsert(self, data: dict[str, dict[str, Any]]) -> None:
    # logger.debug(f"[{self.workspace}] Inserting {len(data)} to {self.namespace}")
    if not data:
        return

    # Ensure collection is loaded before upserting
    self._ensure_collection_loaded()

    import time

    current_time = int(time.time())

    list_data: list[dict[str, Any]] = [
        {
            "id": k,
            "created_at": current_time,
            **{k1: v1 for k1, v1 in v.items() if k1 in self.meta_fields},
        }
        for k, v in data.items()
    ]
    contents = [v["content"] for v in data.values()]
    batches = [
        contents[i : i + self._max_batch_size]
        for i in range(0, len(contents), self._max_batch_size)
    ]

    embedding_tasks = [self.embedding_func(batch) for batch in batches]
    embeddings_list = await asyncio.gather(*embedding_tasks)

    embeddings = np.concatenate(embeddings_list)
    for i, d in enumerate(list_data):
        d["vector"] = embeddings[i]
    results = self._client.upsert(
        collection_name=self.final_namespace, data=list_data
    )
    return results

async def get_vectors_by_ids(self, ids: list[str]) -> dict[str, list[float]]:
    """Get vectors by their IDs, returning only ID and vector data for efficiency

    Args:
        ids: List of unique identifiers

    Returns:
        Dictionary mapping IDs to their vector embeddings
        Format: {id: [vector_values], ...}
    """
    if not ids:
        return {}

    try:
        # Ensure collection is loaded before querying
        self._ensure_collection_loaded()

        # Prepare the ID filter expression
        id_list = '", "'.join(ids)
        filter_expr = f'id in ["{id_list}"]'

        # Query Milvus with the filter, requesting only vector field
        result = self._client.query(
            collection_name=self.final_namespace,
            filter=filter_expr,
            output_fields=["vector"],
        )

        vectors_dict = {}
        for item in result:
            if item and "vector" in item and "id" in item:
                # Convert numpy array to list if needed
                vector_data = item["vector"]
                if isinstance(vector_data, np.ndarray):
                    vector_data = vector_data.tolist()
                vectors_dict[item["id"]] = vector_data

        return vectors_dict
    except Exception as e:
        logger.error(
            f"[{self.workspace}] Error retrieving vectors by IDs from {self.namespace}: {e}"
        )
        return {}

def clean_str(input: Any) -> str:
    """Clean an input string by removing HTML escapes, control characters, and other unwanted characters."""
    # If we get non-string input, just give it back
    if not isinstance(input, str):
        return input

    result = html.unescape(input.strip())
    # https://stackoverflow.com/questions/4324790/removing-control-characters-from-a-string-in-python
    return re.sub(r"[\x00-\x1f\x7f-\x9f]", "", result)

class TokenTracker:
    """Track token usage for LLM calls."""

    def __init__(self):
        self.reset()

    def __enter__(self):
        self.reset()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        print(self)

    def reset(self):
        self.prompt_tokens = 0
        self.completion_tokens = 0
        self.total_tokens = 0
        self.call_count = 0

    def add_usage(self, token_counts):
        """Add token usage from one LLM call.

        Args:
            token_counts: A dictionary containing prompt_tokens, completion_tokens, total_tokens
        """
        self.prompt_tokens += token_counts.get("prompt_tokens", 0)
        self.completion_tokens += token_counts.get("completion_tokens", 0)

        # If total_tokens is provided, use it directly; otherwise calculate the sum
        if "total_tokens" in token_counts:
            self.total_tokens += token_counts["total_tokens"]
        else:
            self.total_tokens += token_counts.get(
                "prompt_tokens", 0
            ) + token_counts.get("completion_tokens", 0)

        self.call_count += 1

    def get_usage(self):
        """Get current usage statistics."""
        return {
            "prompt_tokens": self.prompt_tokens,
            "completion_tokens": self.completion_tokens,
            "total_tokens": self.total_tokens,
            "call_count": self.call_count,
        }

    def __str__(self):
        usage = self.get_usage()
        return (
            f"LLM call count: {usage['call_count']}, "
            f"Prompt tokens: {usage['prompt_tokens']}, "
            f"Completion tokens: {usage['completion_tokens']}, "
            f"Total tokens: {usage['total_tokens']}"
        )

class BasePage(GenericModel, Generic[_T]):
    """
    Defines the core interface for pagination.

    Type Args:
        ModelT: The pydantic model that represents an item in the response.

    Methods:
        has_next_page(): Check if there is another page available
        next_page_info(): Get the necessary information to make a request for the next page
    """

    _options: FinalRequestOptions = PrivateAttr()
    _model: Type[_T] = PrivateAttr()

    def has_next_page(self) -> bool:
        items = self._get_page_items()
        if not items:
            return False
        return self.next_page_info() is not None

    def next_page_info(self) -> Optional[PageInfo]: ...

    def _get_page_items(self) -> Iterable[_T]:  # type: ignore[empty-body]
        ...

    def _params_from_url(self, url: URL) -> httpx.QueryParams:
        # TODO: do we have to preprocess params here?
        return httpx.QueryParams(cast(Any, self._options.params)).merge(url.params)

    def _info_to_options(self, info: PageInfo) -> FinalRequestOptions:
        options = model_copy(self._options)
        options._strip_raw_response_header()

        if not isinstance(info.params, NotGiven):
            options.params = {**options.params, **info.params}
            return options

        if not isinstance(info.url, NotGiven):
            params = self._params_from_url(info.url)
            url = info.url.copy_with(params=params)
            options.params = dict(url.params)
            options.url = str(url)
            return options

        if not isinstance(info.json, NotGiven):
            if not is_mapping(info.json):
                raise TypeError("Pagination is only supported with mappings")

            if not options.json_data:
                options.json_data = {**info.json}
            else:
                if not is_mapping(options.json_data):
                    raise TypeError("Pagination is only supported with mappings")

                options.json_data = {**options.json_data, **info.json}
            return options

        raise ValueError("Unexpected PageInfo state")

