async def save_response_media(response, prompt: str, tags: list[str] = [], transcript: str = None, content_type: str = None) -> AsyncIterator:
    """Save media from response to local file and return URL"""
    if isinstance(response, dict):
        content_type = response.get("mimeType", content_type or "audio/mpeg")
        transcript = response.get("transcript")
        response = response.get("data")
    elif hasattr(response, "headers"):
        content_type = response.headers.get("content-type", content_type)
    elif not content_type:
        raise ValueError("Response must be a dict or have headers")

    if isinstance(response, str):
        response = base64.b64decode(response)
    extension = MEDIA_TYPE_MAP.get(content_type)
    if extension is None:
        raise ValueError(f"Unsupported media type: {content_type}")

    filename = get_filename(tags, prompt, f".{extension}", prompt)
    if hasattr(response, "headers"):
        filename = update_filename(response, filename)
    target_path = os.path.join(get_media_dir(), filename)
    ensure_media_dir()
    with open(target_path, 'wb') as f:
        if isinstance(response, bytes):
            f.write(response)
        else:
            if hasattr(response, "iter_content"):
                iter_response = response.iter_content()
            else:
                iter_response = response.content.iter_any()
            async for chunk in iter_response:
                f.write(chunk)

    # Base URL without request parameters
    media_url = f"/media/{filename}"

    # Save the original URL in the metadata, but not in the file path itself
    source_url = None
    if hasattr(response, "url") and response.method == "GET":
        source_url = str(response.url)

    if content_type.startswith("audio/"):
        yield AudioResponse(media_url, transcript, source_url=source_url)
    elif content_type.startswith("video/"):
        yield VideoResponse(media_url, prompt, source_url=source_url)
    else:
        yield ImageResponse(media_url, prompt, source_url=source_url)

class MarkItDown(BaseMarkItDown):
    """(In preview) An extremely simple text-based document reader, suitable for LLM use.
    This reader will convert common file-types or webpages to Markdown."""

    def __init__(
        self,
        **kwargs,
    ):
        super().__init__(**kwargs)
        self.register_converter(AudioConverter())
        self.register_converter(ImageConverter())

    def _convert(
        self, *, file_stream: BinaryIO, stream_info_guesses: List[StreamInfo], **kwargs
    ) -> DocumentConverterResult:
        res: Union[None, DocumentConverterResult] = None

        # Keep track of which converters throw exceptions
        failed_attempts: List[FailedConversionAttempt] = []

        # Create a copy of the page_converters list, sorted by priority.
        # We do this with each call to _convert because the priority of converters may change between calls.
        # The sort is guaranteed to be stable, so converters with the same priority will remain in the same order.
        sorted_registrations = sorted(self._converters, key=lambda x: x.priority)

        # Remember the initial stream position so that we can return to it
        cur_pos = file_stream.tell()

        for stream_info in stream_info_guesses + [StreamInfo()]:
            for converter_registration in sorted_registrations:
                converter = converter_registration.converter
                # Sanity check -- make sure the cur_pos is still the same
                assert (
                    cur_pos == file_stream.tell()
                ), f"File stream position should NOT change between guess iterations"

                _kwargs = {k: v for k, v in kwargs.items()}

                # Copy any additional global options
                if "llm_client" not in _kwargs and self._llm_client is not None:
                    _kwargs["llm_client"] = self._llm_client

                if "llm_model" not in _kwargs and self._llm_model is not None:
                    _kwargs["llm_model"] = self._llm_model

                if "style_map" not in _kwargs and self._style_map is not None:
                    _kwargs["style_map"] = self._style_map

                if "exiftool_path" not in _kwargs and self._exiftool_path is not None:
                    _kwargs["exiftool_path"] = self._exiftool_path

                # Add the list of converters for nested processing
                _kwargs["_parent_converters"] = self._converters

                # Add legaxy kwargs
                if stream_info is not None:
                    if stream_info.extension is not None:
                        _kwargs["file_extension"] = stream_info.extension

                    if stream_info.url is not None:
                        _kwargs["url"] = stream_info.url

                # Check if the converter will accept the file, and if so, try to convert it
                _accepts = False
                try:
                    _accepts = converter.accepts(file_stream, stream_info, **_kwargs)
                except NotImplementedError:
                    pass

                # accept() should not have changed the file stream position
                assert (
                    cur_pos == file_stream.tell()
                ), f"{type(converter).__name__}.accept() should NOT change the file_stream position"

                # Attempt the conversion
                if _accepts:
                    try:
                        res = converter.convert(file_stream, stream_info, **_kwargs)
                    except Exception:
                        failed_attempts.append(
                            FailedConversionAttempt(
                                converter=converter, exc_info=sys.exc_info()
                            )
                        )
                    finally:
                        file_stream.seek(cur_pos)

                if res is not None:
                    if isinstance(res.text_content, str):
                        # Normalize the content
                        res.text_content = "\n".join(
                            [line.rstrip() for line in re.split(r"\r?\n", res.text_content)]
                        )
                        res.text_content = re.sub(r"\n{3,}", "\n\n", res.text_content)
                    return res

        # If we got this far without success, report any exceptions
        if len(failed_attempts) > 0:
            raise FileConversionException(attempts=failed_attempts)

        # Nothing can handle it!
        raise UnsupportedFormatException(
            f"Could not convert stream to Markdown. No converter attempted a conversion, suggesting that the filetype is simply not supported."
        )

    def convert_stream(
        self,
        stream: BinaryIO,
        *,
        stream_info: Optional[StreamInfo] = None,
        file_extension: Optional[str] = None,  # Deprecated -- use stream_info
        url: Optional[str] = None,  # Deprecated -- use stream_info
        **kwargs: Any,
    ) -> DocumentConverterResult:
        guesses: List[StreamInfo] = []

        # Do we have anything on which to base a guess?
        base_guess = None
        if stream_info is not None or file_extension is not None or url is not None:
            # Start with a non-Null base guess
            if stream_info is None:
                base_guess = StreamInfo()
            else:
                base_guess = stream_info

            if file_extension is not None:
                # Deprecated -- use stream_info
                assert base_guess is not None  # for mypy
                base_guess = base_guess.copy_and_update(extension=file_extension)

            if url is not None:
                # Deprecated -- use stream_info
                assert base_guess is not None  # for mypy
                base_guess = base_guess.copy_and_update(url=url)

        # Check if we have a seekable stream. If not, load the entire stream into memory.
        if not hasattr(stream, "seekable") or not stream.seekable():
            buffer = io.BytesIO()
            while True:
                chunk = stream.read(4096)
                if not chunk:
                    break
                buffer.write(chunk)
            buffer.seek(0)
            stream = buffer

        # Add guesses based on stream content
        guesses = self._get_stream_info_guesses(
            file_stream=stream, base_guess=base_guess or StreamInfo()
        )
        return self._convert(file_stream=stream, stream_info_guesses=guesses, **kwargs)

class ContentReferences:
    def __init__(self) -> None:
        self.list: List[Dict[str, Any]] = []

    def add_reference(self, reference_part: dict) -> None:
        self.list.append(reference_part)

    def merge_reference(self, idx: int, reference_part: dict):
        while len(self.list) <= idx:
            self.list.append({})

        self.list[idx] = {**self.list[idx], **reference_part}

    def update_reference(self, idx: int, operation: str, field: str, value: Any, ref_idx = None) -> None:
        while len(self.list) <= idx:
            self.list.append({})

        if operation == "append" or operation == "add":
            if not isinstance(self.list[idx].get(field, None), list):
                self.list[idx][field] = []
            if isinstance(value, list):
                self.list[idx][field].extend(value)
            else:    
                self.list[idx][field].append(value)

        if operation == "replace" and ref_idx is not None:
            if field == "refs" and not isinstance(self.list[idx].get(field, None), list):
                self.list[idx][field] = []

            if isinstance(self.list[idx][field], list):
                if len(self.list[idx][field]) <= ref_idx:
                    self.list[idx][field].append(value)
                else:
                    self.list[idx][field][ref_idx] = value
            else:
                self.list[idx][field] = value

    def get_ref_info(
        self, 
        source: Dict[str, str], 
        target_ref_info: Dict[str, Union[str, int]]
    ) -> dict[str, str|int] | None:
        for idx, ref_info in enumerate(source.get("refs", [])) or []:
            if not isinstance(ref_info, dict):
                continue

            ref_index = ref_info.get("ref_index", None)
            ref_type = ref_info.get("ref_type", None)
            if isinstance(ref_index, int) and isinstance(ref_type, str):
                if (not target_ref_info or 
                    (target_ref_info["ref_index"] == ref_index and 
                     target_ref_info["ref_type"] == ref_type)):
                    return {
                        "ref_index": ref_index, 
                        "ref_type": ref_type,
                        "idx": idx
                    }

        return None

    def get_reference(self, ref_info: Dict[str, Union[str, int]]) -> Any:
        for reference in self.list:
            reference_ref_info = self.get_ref_info(reference, ref_info)

            if (not reference_ref_info or 
                reference_ref_info["ref_index"] != ref_info["ref_index"] or 
                reference_ref_info["ref_type"] != ref_info["ref_type"]):
                continue

            if ref_info["ref_type"] != "image":
                return reference

            images = reference.get("images", [])
            if isinstance(images, list) and len(images) > reference_ref_info["idx"]:
                return images[reference_ref_info["idx"]]

        return None

    def _load_plugin(self, plugin_path, args=None, config=None):
        """Load the plugin, init it and add to the _plugin dict."""
        # Load the plugin class
        try:
            # Import the plugin
            plugin = import_module('glances.plugins.' + plugin_path)
            # Init and add the plugin to the dictionary
            if hasattr(plugin, 'PluginModel'):
                # Old fashion way to load the plugin (before Glances 5.0)
                # Should be removed in Glances 5.0 - see #3170
                self._plugins[plugin_path] = getattr(plugin, 'PluginModel')(args=args, config=config)
                logger.warning(
                    f'The {plugin_path} plugin class name is "PluginModel" and it is deprecated, \
please rename it to "{plugin_path.capitalize()}Plugin"'
                )
            elif hasattr(plugin, plugin_path.capitalize() + 'Plugin'):
                # New fashion way to load the plugin (after Glances 5.0)
                self._plugins[plugin_path] = getattr(plugin, plugin_path.capitalize() + 'Plugin')(
                    args=args, config=config
                )
        except Exception as e:
            # If a plugin can not be loaded, display a critical message
            # on the console but do not crash
            logger.critical(f"Error while initializing the {plugin_path} plugin ({e})")
            logger.error(traceback.format_exc())
            # An error occurred, disable the plugin
            if args is not None:
                setattr(args, 'disable_' + plugin_path, False)
        else:
            # Manage the default status of the plugin (enable or disable)
            if args is not None:
                # If the all keys are set in the disable_plugin option then look in the enable_plugin option
                if getattr(args, 'disable_all', False):
                    logger.debug('%s => %s', plugin_path, getattr(args, 'enable_' + plugin_path, False))
                    setattr(args, 'disable_' + plugin_path, not getattr(args, 'enable_' + plugin_path, False))
                else:
                    setattr(args, 'disable_' + plugin_path, getattr(args, 'disable_' + plugin_path, False))

def load_additional_plugins(self, args=None, config=None):
    """Load additional plugins if defined"""

    def get_addl_plugins(self, plugin_path):
        """Get list of additional plugins"""
        _plugin_list = []
        for plugin in os.listdir(plugin_path):
            path = os.path.join(plugin_path, plugin)
            if os.path.isdir(path) and not path.startswith('__'):
                # Poor man's walk_pkgs - can't use pkgutil as the module would be already imported here!
                for fil in pathlib.Path(path).glob('*.py'):
                    if fil.is_file():
                        with open(fil) as fd:
                            # The first test should be removed in Glances 5.x - see #3170
                            if 'PluginModel' in fd.read() or plugin.capitalize() + 'Plugin' in fd.read():
                                _plugin_list.append(plugin)
                                break

        return _plugin_list

    path = None
    # Skip section check as implied by has_option
    if config and config.parser.has_option('global', 'plugin_dir'):
        path = config.parser['global']['plugin_dir']

    if args and 'plugin_dir' in args and args.plugin_dir:
        path = args.plugin_dir

    if path:
        # Get list before starting the counter
        _sys_path = sys.path
        start_duration = Counter()
        # Ensure that plugins can be found in plugin_dir
        sys.path.insert(0, path)
        for plugin in get_addl_plugins(self, path):
            if plugin in sys.modules:
                logger.warn(f"Plugin {plugin} already in sys.modules, skipping (workaround: rename plugin)")
            else:
                start_duration.reset()
                try:
                    _mod_loaded = import_module(plugin + '.model')
                    self._plugins[plugin] = _mod_loaded.PluginModel(args=args, config=config)
                    logger.debug(f"Plugin {plugin} started in {start_duration.get()} seconds")
                except Exception as e:
                    # If a plugin can not be loaded, display a critical message
                    # on the console but do not crash
                    logger.critical(f"Error while initializing the {plugin} plugin ({e})")
                    logger.error(traceback.format_exc())
                    # An error occurred, disable the plugin
                    if args:
                        setattr(args, 'disable_' + plugin, False)

        sys.path = _sys_path
        # Log plugins list
        logger.debug(f"Active additional plugins list: {self.getPluginsList()}")

def end(self):
    """End of the Glances stats."""
    # Close export modules
    for e in self._exports:
        self._exports[e].exit()
    # Close plugins
    for p in self._plugins:
        self._plugins[p].exit()
        self._plugins[p].exit()

def is_enabled(self, plugin_name=None):
    """Return true if plugin is enabled."""
    if not plugin_name:
        plugin_name = self.plugin_name
    try:
        d = getattr(self.args, 'disable_' + plugin_name)
    except AttributeError:
        d = getattr(self.args, 'enable_' + plugin_name, True)
    return d is False

def _split_segments_by_timestamps(
    self,
    tokenizer: Tokenizer,
    tokens: List[int],
    time_offset: float,
    segment_size: int,
    segment_duration: float,
    seek: int,
) -> List[List[int]]:
    current_segments = []
    single_timestamp_ending = (
        len(tokens) >= 2 and tokens[-2] < tokenizer.timestamp_begin <= tokens[-1]
    )

    consecutive_timestamps = [
        i
        for i in range(len(tokens))
        if i > 0
        and tokens[i] >= tokenizer.timestamp_begin
        and tokens[i - 1] >= tokenizer.timestamp_begin
    ]

    if len(consecutive_timestamps) > 0:
        slices = list(consecutive_timestamps)
        if single_timestamp_ending:
            slices.append(len(tokens))

        last_slice = 0
        for current_slice in slices:
            sliced_tokens = tokens[last_slice:current_slice]
            start_timestamp_position = sliced_tokens[0] - tokenizer.timestamp_begin
            end_timestamp_position = sliced_tokens[-1] - tokenizer.timestamp_begin
            start_time = (
                time_offset + start_timestamp_position * self.time_precision
            )
            end_time = time_offset + end_timestamp_position * self.time_precision

            current_segments.append(
                dict(
                    seek=seek,
                    start=start_time,
                    end=end_time,
                    tokens=sliced_tokens,
                )
            )
            last_slice = current_slice

        if single_timestamp_ending:
            # single timestamp at the end means no speech after the last timestamp.
            seek += segment_size
        else:
            # otherwise, ignore the unfinished segment and seek to the last timestamp
            last_timestamp_position = (
                tokens[last_slice - 1] - tokenizer.timestamp_begin
            )
            seek += last_timestamp_position * self.input_stride

    else:
        duration = segment_duration
        timestamps = [
            token for token in tokens if token >= tokenizer.timestamp_begin
        ]
        if len(timestamps) > 0 and timestamps[-1] != tokenizer.timestamp_begin:
            last_timestamp_position = timestamps[-1] - tokenizer.timestamp_begin
            duration = last_timestamp_position * self.time_precision

        current_segments.append(
            dict(
                seek=seek,
                start=time_offset,
                end=time_offset + duration,
                tokens=tokens,
            )
        )

        seek += segment_size

    return current_segments, seek, single_timestamp_ending

def load(self) -> Image.core.PixelAccess | None:
    """Load image data based on tile list"""

    if not self.tile and self._im is None:
        msg = "cannot load this image"
        raise OSError(msg)

    pixel = Image.Image.load(self)
    if not self.tile:
        return pixel

    self.map: mmap.mmap | None = None
    use_mmap = self.filename and len(self.tile) == 1

    readonly = 0

    # look for read/seek overrides
    if hasattr(self, "load_read"):
        read = self.load_read
        # don't use mmap if there are custom read/seek functions
        use_mmap = False
    else:
        read = self.fp.read

    if hasattr(self, "load_seek"):
        seek = self.load_seek
        use_mmap = False
    else:
        seek = self.fp.seek

    if use_mmap:
        # try memory mapping
        decoder_name, extents, offset, args = self.tile[0]
        if isinstance(args, str):
            args = (args, 0, 1)
        if (
            decoder_name == "raw"
            and isinstance(args, tuple)
            and len(args) >= 3
            and args[0] == self.mode
            and args[0] in Image._MAPMODES
        ):
            if offset < 0:
                msg = "Tile offset cannot be negative"
                raise ValueError(msg)
            try:
                # use mmap, if possible
                import mmap

                with open(self.filename) as fp:
                    self.map = mmap.mmap(fp.fileno(), 0, access=mmap.ACCESS_READ)
                if offset + self.size[1] * args[1] > self.map.size():
                    msg = "buffer is not large enough"
                    raise OSError(msg)
                self.im = Image.core.map_buffer(
                    self.map, self.size, decoder_name, offset, args
                )
                readonly = 1
                # After trashing self.im,
                # we might need to reload the palette data.
                if self.palette:
                    self.palette.dirty = 1
            except (AttributeError, OSError, ImportError):
                self.map = None

    self.load_prepare()
    err_code = -3  # initialize to unknown error
    if not self.map:
        # sort tiles in file order
        self.tile.sort(key=_tilesort)

        # FIXME: This is a hack to handle TIFF's JpegTables tag.
        prefix = getattr(self, "tile_prefix", b"")

        # Remove consecutive duplicates that only differ by their offset
        self.tile = [
            list(tiles)[-1]
            for _, tiles in itertools.groupby(
                self.tile, lambda tile: (tile[0], tile[1], tile[3])
            )
        ]
        for i, (decoder_name, extents, offset, args) in enumerate(self.tile):
            seek(offset)
            decoder = Image._getdecoder(
                self.mode, decoder_name, args, self.decoderconfig
            )
            try:
                decoder.setimage(self.im, extents)
                if decoder.pulls_fd:
                    decoder.setfd(self.fp)
                    err_code = decoder.decode(b"")[1]
                else:
                    b = prefix
                    while True:
                        read_bytes = self.decodermaxblock
                        if i + 1 < len(self.tile):
                            next_offset = self.tile[i + 1].offset
                            if next_offset > offset:
                                read_bytes = next_offset - offset
                        try:
                            s = read(read_bytes)
                        except (IndexError, struct.error) as e:
                            # truncated png/gif
                            if LOAD_TRUNCATED_IMAGES:
                                break
                            else:
                                msg = "image file is truncated"
                                raise OSError(msg) from e

                        if not s:  # truncated jpeg
                            if LOAD_TRUNCATED_IMAGES:
                                break
                            else:
                                msg = (
                                    "image file is truncated "
                                    f"({len(b)} bytes not processed)"
                                )
                                raise OSError(msg)

                        b = b + s
                        n, err_code = decoder.decode(b)
                        if n < 0:
                            break
                        b = b[n:]
            finally:
                # Need to cleanup here to prevent leaks
                decoder.cleanup()

    self.tile = []
    self.readonly = readonly

    self.load_end()

    if self._exclusive_fp and self._close_exclusive_fp_after_loading:
        self.fp.close()
    self.fp = None

    if not self.map and not LOAD_TRUNCATED_IMAGES and err_code < 0:
        # still raised if decoder fails to return anything
        raise _get_oserror(err_code, encoder=False)

    return Image.Image.load(self)

def create_gbr_image(info: dict[str, int] = {}, magic_number=b"") -> BytesIO:
    return BytesIO(
        b"".join(
            _binary.o32be(i)
            for i in [
                info.get("header_size", 20),
                info.get("version", 1),
                info.get("width", 1),
                info.get("height", 1),
                info.get("color_depth", 1),
            ]
        )
        + magic_number
    )

