def _generate_ws_api_signature(self, data: Dict) -> str:
    sig_func = self._hmac_signature
    if self.PRIVATE_KEY:
        if self._is_rsa:
            sig_func = self._rsa_signature
        else:
            sig_func = self._ed25519_signature
    query_string = urlencode(data)
    return sig_func(query_string)

