def max_ddd(arr: array, index: DatetimeIndex) -> IndexRange:
    max_seen = arr[0]
    ddd_start, ddd_end = 0, 0
    ddd = 0
    start = 0
    in_draw_down = False

    i = 0
    for i in range(len(arr)):
        if arr[i] > max_seen:
            if in_draw_down:
                in_draw_down = False
                if i - start > ddd:
                    ddd = i - start
                    ddd_start = start
                    ddd_end = i - 1
            max_seen = arr[i]
        elif arr[i] < max_seen:
            if not in_draw_down:
                in_draw_down = True
                start = i - 1

    if arr[i] < max_seen:
        if i - start > ddd:
            return IndexRange.new(start, i, index)

    return IndexRange.new(ddd_start, ddd_end, index)

async def send(
    self,
    message: discord.Message,
    destination: typing.Union[
        discord.TextChannel, discord.DMChannel, discord.User, discord.Member
    ] = None,
    from_mod: bool = False,
    note: bool = False,
    anonymous: bool = False,
    plain: bool = False,
    persistent_note: bool = False,
    thread_creation: bool = False,
) -> None:
    if not note and from_mod:
        self.bot.loop.create_task(self._restart_close_timer())  # Start or restart thread auto close

    if self.close_task is not None:
        # cancel closing if a thread message is sent.
        self.bot.loop.create_task(self.cancel_closure())
        self.bot.loop.create_task(
            self.channel.send(
                embed=discord.Embed(
                    color=self.bot.error_color,
                    description="Scheduled close has been cancelled.",
                )
            )
        )

    if not self.ready:
        await self.wait_until_ready()

    if not from_mod and not note:
        self.bot.loop.create_task(self.bot.api.append_log(message, channel_id=self.channel.id))

    destination = destination or self.channel

    if destination is None:
        logger.error("Attempted to send a message to a thread with no channel (destination is None).")
        return
    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found when trying to send message.")
        return

    author = message.author
    member = self.bot.guild.get_member(author.id)
    if member:
        avatar_url = member.display_avatar.url
    else:
        avatar_url = author.display_avatar.url

    #  Extract content for blank/forwarded messages ---
    content = message.content
    if not content:
        # Try to extract from referenced message (replies)
        if hasattr(message, "reference") and message.reference is not None:
            try:
                ref = message.reference.resolved
                if ref and hasattr(ref, "content") and ref.content:
                    content = f"(Reply to: {ref.author}: {ref.content})"
            except Exception:
                pass
        # Try to extract from first embed's description
        if not content and message.embeds:
            first_embed = message.embeds[0]
            if hasattr(first_embed, "description") and first_embed.description:
                content = first_embed.description
        # Fallback: show something generic if still blank
        if not content:
            content = "[This is a forwarded message.]"

    embed = discord.Embed(description=content)
    if self.bot.config["show_timestamp"]:
        embed.timestamp = message.created_at

    system_avatar_url = "https://discordapp.com/assets/f78426a064bc9dd24847519259bc42af.png"

    if not note:
        if anonymous and from_mod and not isinstance(destination, discord.TextChannel):
            # Anonymously sending to the user.
            tag = self.bot.config["mod_tag"]
            if tag is None:
                tag = str(get_top_role(author, self.bot.config["use_hoisted_top_role"]))
            name = self.bot.config["anon_username"]
            if name is None:
                name = tag
            avatar_url = self.bot.config["anon_avatar_url"]
            if avatar_url is None:
                avatar_url = self.bot.get_guild_icon(guild=self.bot.guild, size=128)
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/channels/{self.bot.guild.id}#{message.id}",
            )
        else:
            # Normal message
            name = str(author)
            avatar_url = avatar_url
            embed.set_author(
                name=name,
                icon_url=avatar_url,
                url=f"https://discordapp.com/users/{author.id}#{message.id}",
            )
    else:
        # Notes are just replies with a different footer and color
        embed.set_author(
            name=str(author),
            icon_url=avatar_url,
            url=f"https://discordapp.com/users/{author.id}#{message.id}",
        )

    ext = [(a.url, a.filename, False) for a in message.attachments]

    images = []
    attachments = []
    for attachment in ext:
        if is_image_url(attachment[0]):
            images.append(attachment)
        else:
            attachments.append(attachment)

    image_urls = re.findall(
        r"http[s]?:\/\/(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*(),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+",
        message.content,
    )

    image_urls = [
        (is_image_url(url, convert_size=False), None, False)
        for url in image_urls
        if is_image_url(url, convert_size=False)
    ]
    images.extend(image_urls)

    def lottie_to_png(data):
        importer = l_importers.get("lottie")
        exporter = l_exporters.get("png")
        with io.BytesIO() as stream:
            stream.write(data)
            stream.seek(0)
            an = importer.process(stream)

        with io.BytesIO() as stream:
            exporter.process(an, stream)
            stream.seek(0)
            return stream.read()

    for i in message.stickers:
        if i.format in (
            discord.StickerFormatType.png,
            discord.StickerFormatType.apng,
            discord.StickerFormatType.gif,
        ):
            images.append(
                (f"https://media.discordapp.net/stickers/{i.id}.{i.format.file_extension}", i.name, True)
            )
        elif i.format == discord.StickerFormatType.lottie:
            # save the json lottie representation
            try:
                async with self.bot.session.get(i.url) as resp:
                    data = await resp.read()

                # convert to a png
                img_data = await self.bot.loop.run_in_executor(
                    None, functools.partial(lottie_to_png, data)
                )
                b64_data = base64.b64encode(img_data).decode()

                # upload to imgur
                async with self.bot.session.post(
                    "https://api.imgur.com/3/image",
                    headers={"Authorization": "Client-ID 50e96145ac5e085"},
                    data={"image": b64_data},
                ) as resp:
                    result = await resp.json()
                    url = result["data"]["link"]

            except Exception:
                traceback.print_exc()
                images.append((None, i.name, True))
            else:
                images.append((url, i.name, True))
        else:
            images.append((None, i.name, True))

    embedded_image = False

    prioritize_uploads = any(i[1] is not None for i in images)

    additional_images = []
    additional_count = 1

    for url, filename, is_sticker in images:
        if (
            not prioritize_uploads or ((url is None or is_image_url(url)) and filename)
        ) and not embedded_image:
            if url is not None:
                embed.set_image(url=url)
            if filename:
                if is_sticker:
                    if url is None:
                        description = f"{filename}: Unable to retrieve sticker image"
                    else:
                        description = f"[{filename}]({url})"
                    embed.add_field(name="Sticker", value=description)
                else:
                    embed.add_field(name="Image", value=f"[{filename}]({url})")
            embedded_image = True
        else:
            if note:
                color = self.bot.main_color
            elif from_mod:
                color = self.bot.mod_color
            else:
                color = self.bot.recipient_color

            img_embed = discord.Embed(color=color)

            if url is not None:
                img_embed.set_image(url=url)
                img_embed.url = url
            if filename is not None:
                img_embed.title = filename
            img_embed.set_footer(text=f"Additional Image Upload ({additional_count})")
            img_embed.timestamp = message.created_at
            additional_images.append(destination.send(embed=img_embed))
            additional_count += 1

    file_upload_count = 1

    for url, filename, _ in attachments:
        embed.add_field(name=f"File upload ({file_upload_count})", value=f"[{filename}]({url})")
        file_upload_count += 1

    if from_mod:
        embed.colour = self.bot.mod_color
        if note:
            embed.set_footer(text=f"{'Persistent' if persistent_note else ''} Internal Message")
        # Anonymous reply sent in thread channel
        elif anonymous and isinstance(destination, discord.TextChannel):
            embed.set_footer(text="Anonymous Reply")
        # Normal messages
        elif not anonymous:
            mod_tag = self.bot.config["mod_tag"]
            if mod_tag is None:
                mod_tag = str(get_top_role(message.author, self.bot.config["use_hoisted_top_role"]))
            embed.set_footer(text=mod_tag)  # Normal messages
        else:
            embed.set_footer(text=self.bot.config["anon_tag"])
    else:
        embed.set_footer(text=f"Message ID: {message.id}")
        embed.colour = self.bot.recipient_color

    if (from_mod or note) and not thread_creation:
        delete_message = not bool(message.attachments)
        if delete_message and destination == self.channel:
            try:
                await message.delete()
            except Exception as e:
                logger.warning("Cannot delete message: %s.", e)

    if (
        from_mod
        and self.bot.config["dm_disabled"] == DMDisabled.ALL_THREADS
        and destination != self.channel
    ):
        logger.info("Sending a message to %s when DM disabled is set.", self.recipient)

    try:
        await destination.typing()
    except discord.NotFound:
        logger.warning("Channel not found.")
        raise

    if not from_mod and not note:
        mentions = await self.get_notifications()
    else:
        mentions = None

    if plain:
        if from_mod and not isinstance(destination, discord.TextChannel):
            # Plain to user
            with warnings.catch_warnings():
                # Catch coroutines not awaited warning
                warnings.simplefilter("ignore")
                additional_images = []

            if embed.footer.text:
                plain_message = f"**{embed.footer.text} "
            else:
                plain_message = "**"
            plain_message += f"{embed.author.name}:** {embed.description}"
            files = []
            for i in message.attachments:
                files.append(await i.to_file())

            msg = await destination.send(plain_message, files=files)
        else:
            # Plain to mods
            embed.set_footer(text="[PLAIN] " + embed.footer.text)
            msg = await destination.send(mentions, embed=embed)

    else:
        msg = await destination.send(mentions, embed=embed)

    if additional_images:
        self.ready = False
        await asyncio.gather(*additional_images)
        self.ready = True

    return msg

def run(self):
    async def runner():
        async with self:
            self._connected = asyncio.Event()
            self.session = ClientSession(loop=self.loop)

            if self.config["enable_presence_intent"]:
                logger.info("Starting bot with presence intent.")
            else:
                logger.info("Starting bot without presence intent.")

            try:
                await self.start(self.token)
            except discord.PrivilegedIntentsRequired:
                logger.critical(
                    "Privileged intents are not explicitly granted in the discord developers dashboard."
                )
            except discord.LoginFailure:
                logger.critical("Invalid token")
            except Exception:
                logger.critical("Fatal exception", exc_info=True)
            finally:
                if self.session:
                    await self.session.close()
                if not self.is_closed():
                    await self.close()

    async def _cancel_tasks():
        async with self:
            task_retriever = asyncio.all_tasks
            loop = self.loop
            tasks = {t for t in task_retriever() if not t.done() and t.get_coro() != cancel_tasks_coro}

            if not tasks:
                return

            logger.info("Cleaning up after %d tasks.", len(tasks))
            for task in tasks:
                task.cancel()

            await asyncio.gather(*tasks, return_exceptions=True)
            logger.info("All tasks finished cancelling.")

            for task in tasks:
                try:
                    if task.exception() is not None:
                        loop.call_exception_handler(
                            {
                                "message": "Unhandled exception during Client.run shutdown.",
                                "exception": task.exception(),
                                "task": task,
                            }
                        )
                except (asyncio.InvalidStateError, asyncio.CancelledError):
                    pass

    try:
        asyncio.run(runner(), debug=bool(os.getenv("DEBUG_ASYNCIO")))
    except (KeyboardInterrupt, SystemExit):
        logger.info("Received signal to terminate bot and event loop.")
    finally:
        logger.info("Cleaning up tasks.")

        try:
            cancel_tasks_coro = _cancel_tasks()
            asyncio.run(cancel_tasks_coro)
        finally:
            logger.info("Closing the event loop.")

def bot_owner_ids(self):
    owner_ids = self.config["owners"]
    if owner_ids is not None:
        owner_ids = set(map(int, str(owner_ids).split(",")))
    if self.owner_id is not None:
        owner_ids.add(self.owner_id)
    permissions = self.config["level_permissions"].get(PermissionLevel.OWNER.name, [])
    for perm in permissions:
        owner_ids.add(int(perm))
    return owner_ids

async def on_command_error(
    self, context: commands.Context, exception: Exception, *, unhandled_by_cog: bool = False
) -> None:
    if not unhandled_by_cog:
        command = context.command
        if command and command.has_error_handler():
            return
        cog = context.cog
        if cog and cog.has_error_handler():
            return

    if isinstance(exception, (commands.BadArgument, commands.BadUnionArgument)):
        await context.typing()
        await context.send(embed=discord.Embed(color=self.error_color, description=str(exception)))
    elif isinstance(exception, commands.CommandNotFound):
        logger.warning("CommandNotFound: %s", exception)
    elif isinstance(exception, commands.MissingRequiredArgument):
        await context.send_help(context.command)
    elif isinstance(exception, commands.CommandOnCooldown):
        await context.send(
            embed=discord.Embed(
                title="Command on cooldown",
                description=f"Try again in {exception.retry_after:.2f} seconds",
                color=self.error_color,
            )
        )
    elif isinstance(exception, commands.CheckFailure):
        for check in context.command.checks:
            if not await check(context):
                if hasattr(check, "fail_msg"):
                    await context.send(
                        embed=discord.Embed(color=self.error_color, description=check.fail_msg)
                    )
                if hasattr(check, "permission_level"):
                    corrected_permission_level = self.command_perm(context.command.qualified_name)
                    logger.warning(
                        "User %s does not have permission to use this command: `%s` (%s).",
                        context.author.name,
                        context.command.qualified_name,
                        corrected_permission_level.name,
                    )
        logger.warning("CheckFailure: %s", exception)
    elif isinstance(exception, commands.DisabledCommand):
        logger.info("DisabledCommand: %s is trying to run eval but it's disabled", context.author.name)
    else:
        logger.error("Unexpected exception:", exc_info=exception)

async def anonadduser(self, ctx, *users_arg: Union[discord.Member, discord.Role, str]):
    """Adds a user to a modmail thread anonymously

    `options` can be `silent` or `silently`.
    """
    silent = False
    users = []
    for u in users_arg:
        if isinstance(u, str):
            if "silent" in u or "silently" in u:
                silent = True
        elif isinstance(u, discord.Role):
            users += u.members
        elif isinstance(u, discord.Member):
            users.append(u)

    for u in users:
        curr_thread = await self.bot.threads.find(recipient=u)
        if curr_thread == ctx.thread:
            users.remove(u)
            continue

        if curr_thread:
            em = discord.Embed(
                title="Error",
                description=f"{u.mention} is already in a thread: {curr_thread.channel.mention}.",
                color=self.bot.error_color,
            )
            await ctx.send(embed=em)
            ctx.command.reset_cooldown(ctx)
            return

    if not users:
        em = discord.Embed(
            title="Error",
            description="All users are already in the thread.",
            color=self.bot.error_color,
        )
        await ctx.send(embed=em)
        ctx.command.reset_cooldown(ctx)
        return

    to_exec = []
    if not silent:
        em = discord.Embed(
            title=self.bot.config["private_added_to_group_title"],
            description=self.bot.config["private_added_to_group_description_anon"],
            color=self.bot.main_color,
        )
        if self.bot.config["show_timestamp"]:
            em.timestamp = discord.utils.utcnow()

        tag = self.bot.config["mod_tag"]
        if tag is None:
            tag = str(get_top_role(ctx.author, self.bot.config["use_hoisted_top_role"]))
        name = self.bot.config["anon_username"]
        if name is None:
            name = tag
        avatar_url = self.bot.config["anon_avatar_url"]
        if avatar_url is None:
            avatar_url = self.bot.get_guild_icon(guild=ctx.guild, size=128)
        em.set_footer(text=name, icon_url=avatar_url if avatar_url else None)

        for u in users:
            to_exec.append(u.send(embed=em))

        description = self.bot.formatter.format(
            self.bot.config["public_added_to_group_description_anon"],
            users=", ".join(u.name for u in users),
        )
        em = discord.Embed(
            title=self.bot.config["public_added_to_group_title"],
            description=description,
            color=self.bot.main_color,
        )
        if self.bot.config["show_timestamp"]:
            em.timestamp = discord.utils.utcnow()
        em.set_footer(
            text=f"{users[0]}", icon_url=users[0].display_avatar.url if users[0].display_avatar else None
        )

        for i in ctx.thread.recipients:
            if i not in users:
                to_exec.append(i.send(embed=em))

    await ctx.thread.add_users(users)
    if to_exec:
        await asyncio.gather(*to_exec)

    sent_emoji, _ = await self.bot.retrieve_emoji()
    await self.bot.add_reaction(ctx.message, sent_emoji)

def parse_image_url(url: str, *, convert_size=True) -> str:
    """
    Convert the image URL into a sized Discord avatar.

    Parameters
    ----------
    url : str
        The URL to convert.

    Returns
    -------
    str
        The converted URL, or '' if the URL isn't in the proper format.
    """
    types = [".png", ".jpg", ".gif", ".jpeg", ".webp"]
    url = parse.urlsplit(url)

    if any(url.path.lower().endswith(i) for i in types):
        if convert_size:
            return parse.urlunsplit((*url[:3], "size=128", url[-1]))
        else:
            return parse.urlunsplit(url)
    return ""

def extract_block_timestamp(reason, id_):
    # etc "blah blah blah... until <t:XX:f>."
    now = discord.utils.utcnow()
    end_time = re.search(r"until <t:(\d+):(?:R|f)>.$", reason)
    attempts = [
        # backwards compat
        re.search(r"until ([^`]+?)\.$", reason),
        re.search(r"%([^%]+?)%", reason),
    ]
    after = None
    if end_time is None:
        for i in attempts:
            if i is not None:
                end_time = i
                break

        if end_time is not None:
            # found a deprecated version
            try:
                after = (
                    datetime.fromisoformat(end_time.group(1)).replace(tzinfo=timezone.utc) - now
                ).total_seconds()
            except ValueError:
                logger.warning(
                    r"Broken block message for user %s, block and unblock again with a different message to prevent further issues",
                    id_,
                )
                raise
            logger.warning(
                r"Deprecated time message for user %s, block and unblock again to update.",
                id_,
            )
    else:
        try:
            after = (
                datetime.utcfromtimestamp(int(end_time.group(1))).replace(tzinfo=timezone.utc) - now
            ).total_seconds()
        except ValueError:
            logger.warning(
                r"Broken block message for user %s, block and unblock again with a different message to prevent further issues",
                id_,
            )
            raise

    return end_time, after

def return_or_truncate(text, max_length):
    if len(text) <= max_length:
        return text
    return text[: max_length - 3] + "..."

